referenceSolutions.javascript:
export function decodeWays(digits        )         {
if(!digits.length)return 0;let a=1,b=digits[0]==='0'?0:1;for(let i=1;i<digits.length;i++){const pair=Number(digits.slice(i-1,i+1));const next=(digits[i]!=='0'?b:0)+(pair>=10&&pair<=26?a:0);a=b;b=next;}return b;
}

